            "ans": "1) الشرط الرياضي المشترك: في كلتيهما يشترط تطابق زوجين من الأضلاع المتناظرة في المثلثين (ضلعان في الأول يطابقان ضلعين في الثاني). 2) متباينة المفصلة (SAS): المعطى هو اختلاف قياس الزاويتين المحصورتين (m∠1 > m∠2)؛ والاستنتاج هو أن الضلع المقابل للزاوية الكبرى أطول من المقابل للصغرى (الضلع الثالث 1 > الضلع الثالث 2). 3) عكس متباينة المفصلة (SSS): المعطى هو اختلاف طولي الضلعين الثالثين (الضلع 1 > الضلع 2)؛ والاستنتاج هو أن الزاوية المحصورة المقابلة للضلع الأطول أكبر من الزاوية المحصورة المقابلة للأقصر (m∠1 > m∠2).",
            "difficulty": "متوسط",
