            "lines": 3,
            "ans": "بما أن الضلع الثالث في الأول أطول من الثاني، فإن الزاوية المحصورة في الأول أكبر من الثاني: 42 > 2x - 8 ⟹ 2x - 8 < 42 ⟹ 2x < 50 ⟹ x < 25. ومن ناحية أخرى، يجب أن تكون الزاوية موجبة تماماً (أكبر من 0°): 2x - 8 > 0 ⟹ 2x > 8 ⟹ x > 4. بدمج المتباينتين: المدى الممكن لقيم x هو المتباينة المركبة: 4 < x < 25.",
            "difficulty": "متوسط",
