      "q": "إذا كانت النقاط <span class=\"sec-math ltr-math\" dir=\"ltr\">A, B, C, D</span> على استقامة واحدة بالترتيب، وكان <span class=\"sec-math ltr-math\" dir=\"ltr\">AB ≅ CD</span>، فأثبت أن <span class=\"sec-math ltr-math\" dir=\"ltr\">AC ≅ BD</span>.",
      "ans": "1) <span class=\"sec-math ltr-math\" dir=\"ltr\">AB ≅ CD</span> (معطى) إذن <span class=\"sec-math ltr-math\" dir=\"ltr\">AB = CD</span> (تعريف التطابق).\n2) <span class=\"sec-math ltr-math\" dir=\"ltr\">BC = BC</span> (خاصية الانعكاس للمساواة).\n3) <span class=\"sec-math ltr-math\" dir=\"ltr\">AB + BC = CD + BC</span> (خاصية الجمع للمساواة).\n4) <span class=\"sec-math ltr-math\" dir=\"ltr\">AC = AB + BC, BD = BC + CD</span> (مسلمة جمع أطوال القطع).\n5) <span class=\"sec-math ltr-math\" dir=\"ltr\">AC = BD</span> (بالتعويض)، إذن <span class=\"sec-math ltr-math\" dir=\"ltr\">AC ≅ BD</span> (تعريف التطابق).",
      "lines": 4,
      "difficulty": "متوسط",
      "marks": 2,
      "source": "مسائل وتطبيقات كتاب الرياضيات 1-1 (الأول الثانوي)"
