      "q": "تقع النقطة <span class=\"sec-math ltr-math\" dir=\"ltr\">M</span> بين <span class=\"sec-math ltr-math\" dir=\"ltr\">P, Q</span>. إذا كان <span class=\"sec-math ltr-math\" dir=\"ltr\">PM = 2x + 1</span> و <span class=\"sec-math ltr-math\" dir=\"ltr\">MQ = 3x - 4</span> و <span class=\"sec-math ltr-math\" dir=\"ltr\">PQ = 22</span>، فأوجد قيمة <span class=\"sec-math ltr-math\" dir=\"ltr\">x</span> وطول <span class=\"sec-math ltr-math\" dir=\"ltr\">PM</span>.",
      "ans": "<span class=\"sec-math ltr-math\" dir=\"ltr\">PM + MQ = PQ → (2x + 1) + (3x - 4) = 22 → 5x - 3 = 22 → 5x = 25 → x = 5</span>.\nطول <span class=\"sec-math ltr-math\" dir=\"ltr\">PM = 2(5) + 1 = 11</span>.",
      "lines": 3,
