      "ans": "لكي يتوازى المستقيمان يجب أن تكون الزاويتان متكاملتين: (3x + 15) + (2x + 35) = 180 ⟹ 5x + 50 = 180 ⟹ 5x = 130 ⟹ x = 26. الزاوية الأولى = 3(26) + 15 = 78 + 15 = 93°. الزاوية الثانية = 2(26) + 35 = 52 + 35 = 87°. نلاحظ 93° + 87° = 180°.",
      "lines": 3,
      "difficulty": "متوسط",
      "marks": 2,
      "source": "مسائل وتطبيقات كتاب الرياضيات 1-1 (الأول الثانوي)"
