      "q": "في مثلث، إذا كانت الزاوية الخارجية قياسها 130°، وكانت إحدى الزاويتين الداخليتين البعيدتين تزيد بمقدار 20° عن الأخرى، فأوجد قياس كل زوايا المثلث الداخلية.",
      "ans": "نفرض الزاويتين الداخليتين البعيدتين هما x و (x + 20). وفق نظرية الزاوية الخارجية: x + (x + 20) = 130 ⟹ 2x + 20 = 130 ⟹ 2x = 110 ⟹ x = 55°. إذن الزاوية الأولى = 55°، والزاوية الثانية = 55° + 20° = 75°. والزاوية المجاورة للزاوية الخارجية = 180° - 130° = 50°. زوايا المثلث هي: 50°, 55°, 75°. (التحقق: 50 + 55 + 75 = 180°).",
      "lines": 3,
      "difficulty": "متوسط",
      "marks": 2,
      "source": "مسائل وتطبيقات كتاب الرياضيات 1-1 (الأول الثانوي)"
