      "ans": "المعطيات: ∠A ≅ ∠D, ∠B ≅ ∠E, والضلع BC ≅ EF. المطلوب: إثبات △ABC ≅ △DEF. البرهان: 1) بما أن ∠A ≅ ∠D و ∠B ≅ ∠E، فإنه وفق نظرية الزاوية الثالثة تكون ∠C ≅ ∠F. 2) الآن لدينا في المثلثين: ∠B ≅ ∠E و الضلع BC ≅ EF و ∠C ≅ ∠F. 3) الضلع BC محصور تماماً بين الزاويتين B و C، والضلع EF محصور بين E و F. 4) إذن △ABC ≅ △DEF بموجب مسلمة ASA، وهو المطلوب.",
      "lines": 3,
