      "q": "قارن تفصيلياً بين مركز الدائرة المحيطة (Circumcenter) ومركز الدائرة الداخلية (Incenter) من حيث: نقطة التلاقي، الخاصية التساوية، وموقع المركز في أنواع المثلثات.",
      "ans": "1) مركز الدائرة المحيطة: نقطة تلاقي الأعمدة المنصفة للأضلاع؛ يبعد أبعاداً متساوية عن الرؤوس الثلاثة؛ يقع داخل المثلث الحاد، وعلى منتصف وتر القائم، وخارج المنفرج. 2) مركز الدائرة الداخلية: نقطة تلاقي منصفات الزوايا الداخلية؛ يبعد أبعاداً متساوية عن الأضلاع الثلاثة (نصف قطر الدائرة الداخلية)؛ يقع داخل المثلث دائماً لجميع أنواع المثلثات.",
