      "q": "حدد موقع ملتقى الارتفاعات (Orthocenter) في الحالات الثلاث: المثلث حاد الزوايا، المثلث قائم الزاوية، والمثلث منفرج الزاوية مع التعليل الهندسي لكل حالة.",
      "ans": "1) المثلث حاد الزوايا: يقع ملتقى الارتفاعات داخل المثلث لأن الأعمدة الثلاثة تسقط جميعها داخل أضلاع المثلث. 2) المثلث قائم الزاوية: يقع ملتقى الارتفاعات عند رأس الزاوية القائمة تحديداً لأن ساقي القائمة يمثلان ارتفاعين للمثلث فيتقاطعان عند الرأس القائم مع الارتفاع الساقط على الوتر. 3) المثلث منفرج الزاوية: يقع ملتقى الارتفاعات خارج المثلث لأن الارتفاعين الساقطين من الزاويتين الحادتين يسقطان على الامتداد الخارجي لضلعي الزاوية المنفرجة.",
