      "q": "اذكر الخطوات الثلاث المنهجية لكتابة برهان غير مباشر (البرهان بالتناقض).",
      "ans": "1) الخطوة الأولى: تحديد النتيجة المطلوب إثباتها، ثم افتراض أن هذه النتيجة خاطئة (أي افتراض نفي النتيجة كفرض مؤقت). 2) الخطوة الثانية: استعمال التبرير المنطقي والاستنتاجي للوصول إلى تناقض صارخ مع المعطيات المعلومة أو مع تعريف أو مسلمة أو نظرية رياضية مثبتة سلفاً. 3) الخطوة الثالثة: بما أن الفرض المؤقت أدى إلى تناقض مستحيل، فإن هذا الفرض باطل حتماً، مما يثبت صحة النتيجة الأصلية المطلوبة.",
