      "ans": "المعطيات: المثلث ABC. المطلوب: إثبات أن المثلث لا يمكن أن يحتوي على زاويتين قائمتين. البرهان غير المباشر: 1) نفترض عكس المطلوب: نفترض أن المثلث ABC يحتوي على زاويتين قائمتين، ولتكونا ∠A = 90° و ∠B = 90°. 2) نعلم أن مجموع زوايا المثلث = 180°: m∠A + m∠B + m∠C = 180° ⟹ 90° + 90° + m∠C = 180° ⟹ 180° + m∠C = 180° ⟹ m∠C = 0°. 3) ولكن لا يمكن لأي زاوية في مثلث أن يكون قياسها 0° (لأن المثلث شكل هندسي مغلق وأضلاعه غير منطبقة)، وهذا تناقض هندسي واضح. 4) إذن الفرض خاطئ، والمثلث لا يمكن أن يحتوي على أكثر من زاوية قائمة واحدة.",
      "lines": 3,
      "difficulty": "متوسط",
      "marks": 2,
      "source": "مسائل وتطبيقات كتاب الرياضيات 1-1 (الأول الثانوي)"
