      "ans": "المعطيات: المثلث ABC. المطلوب: إثبات أن AB + BC > AC. البرهان: نمد الضلع AB من جهة B إلى النقطة D بحيث يكون BD = BC، ونصل CD. المثلث BCD متطابق الضلعين فيه BD = BC، إذن ∠1 ≅ ∠2. في المثلث الكبير ACD: قياس الزاوية ACD = m∠ACB + m∠1 > m∠2 (الكل أكبر من الجزء). بموجب متباينة زاوية-ضلع في △ACD: الضلع المقابل للزاوية الكبرى أطول من المقابل للصغرى، إذن AD > AC. ولكن AD = AB + BD = AB + BC. بالتعويض: AB + BC > AC، وهو المطلوب.",
